window.RP_SESSION={"id":"S-1ef86437e5df","messages":[{"id":"RP-II-0180666","time":"2026-09-05T22:56:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"때는 그날, 양 마수를 쓰러트리고, 텐트를 친 뒤, 티플링 비론소와 잠깐의 대화가 오갔던 그날 밤.\n비론소가 떠난 뒤, 말했다 시피 허그는 그대로 망토를 바닥에 깐 뒤 옆으로 누워 잠을 청했습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180667","time":"2026-09-05T22:56:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180668","time":"2026-09-05T22:57:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"음… 비론소가 뭐라고 말했었더라…\n분명…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180669","time":"2026-09-05T22:58:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"\" ~~~\n\n—그런 모습들요. 사냥감 앞에선 맹랑하고, 당차고. 씩씩하지만, 가끔 허그씨가 조용히 뭔갈 생각하는 모습을 봤어요.\n\n그래서 한 번 물어보고 싶어요.\n\n혹시... 좋아하는 분이 있으신가요? \"","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180670","time":"2026-09-05T23:01:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"푸하하, 다시 생각해봐도 조금 미안한걸.\n나름 무언갈 기대하고 물어본 것 같았었는데 말이야.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180671","time":"2026-09-05T23:01:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그치만, 어쩔 수 없다고? 없는걸 있다고 말하기도 미안하고, 게다가 난 거짓말이나 그런거엔 재주도 없으니까.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180672","time":"2026-09-05T23:03:00+09:00","room":"RP II","name":"베어","profile":"베어","identity":"unresolved","type":"dialogue","body":"허그, 좋아한다고 말해..","characters":[]},{"id":"RP-II-0180673","time":"2026-09-05T23:03:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"여이, 없잖아 허그? 식구들이랑 술이나 한 번씩 다같이 들고~ 수다도 떨고~ 고기도 구워먹고~ 지금도 충분히 좋은데 말이야.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180674","time":"2026-09-05T23:03:00+09:00","room":"RP II","name":"베어","profile":"베어","identity":"unresolved","type":"dialogue","body":"뻬르난떼를 좋아한다고 말해..!","characters":[]},{"id":"RP-II-0180675","time":"2026-09-05T23:03:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"하하하, 그래~\n이런 내가 그닥 누구를 막 좋아하고 그럴 것 까지야…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180676","time":"2026-09-05T23:03:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180677","time":"2026-09-05T23:04:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"사진 2장","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180678","time":"2026-09-05T23:04:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180679","time":"2026-09-05T23:04:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“……”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180680","time":"2026-09-05T23:04:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄아아, 잠이나 자라고!“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180681","time":"2026-09-05T23:04:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0180682","time":"2026-09-05T23:04:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]},{"id":"RP-II-0180683","time":"2026-09-05T23:24:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이후 언제 그랬냐는 듯 커어푸우 잘 잤다네요~","characters":["P-6a1a99e98a44"]}]};
